### Expected Behavior

Get address object in query result


### Actual Behavior

I have a relation between Adress and Order, foreign key is carAddressId in Order entity

```
 syntax error at or near "AND"
```

```typescript

await getRepository(Order).createQueryBuilder('order')
      .innerJoinAndSelect("order.address", "address", "address.id = order.carAddressId")
      .where("order.userId = :userId", { userId })
      .orderBy('order.createDate', 'DESC')
      .getOne();

@Entity({
  name: 'address',
})
export class Address extends BaseEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  address: string;

  @Column({ type: "float" })
  latitude: number;

  @Column({ type: "float" })
  longitude: number;

  @Column()
  userId: string;

  @CreateDateColumn({
    type: "timestamptz",
  })
  createDate: Date;

  @DeleteDateColumn()
  deleteDate?: Date;

  @ManyToOne(type => User, user => user.addressUser)
  addressUser: User;

  @OneToOne(type => Order, order => order.address)
  order: Order;
}

@Entity({
  name: 'orders',
})
export class Order extends CommonEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column('uuid')
  userId: string;

  @Column('uuid')
  updateByUserId: string;

  @Column('uuid')
  carId: string;

  @Column('uuid')
  carAddressId: string;

  @Column({
    type: "timestamptz"
  })
  todoDate: Date;

  @Column()
  comment: string;

  @Column({
    type: "simple-json",
    nullable: true,
  })
  imageArrayId: string[];

  @CreateDateColumn({
    type: "timestamptz"
  })
  updateDate: Date;

  @CreateDateColumn({
    type: "timestamptz"
  })
  createDate: Date;

  @Column({
    enum: PaymentType,
    type: 'enum'
  })
  paymentType: PaymentType;

  @Column({
    enum: OrderStatus,
    type: 'enum',
    default: OrderStatus.WAITING,
  })
  status: OrderStatus;

  @Column({ default: false })
  isOpen: boolean;

  @Column({ default: false })
  accessible: boolean;

  @Column({
    nullable: true,
    type: 'uuid',
  })
  operatorImageId: string;

  @ManyToOne(() => User, user => user.orders)
  user: User;

  @OneToOne(() => Address, address => address.order)
  address: Address;

  @OneToMany(() => OrderChangeHistory, orderChangeHistory => orderChangeHistory.orderId)
  orderChangeHistory: OrderChangeHistory[];

  @OneToMany(() => File, file => file.orders)
  files: File[];
}

```

